export const handleFetchImage = async (imagePath, cb) => {
    let bdy = {
      "query":"getSignedUrl",
      "params":{
          "userId": getStore("profileUser")?.businessId ,
          "fileName": imagePath
      }
    }
    const res = fetchEncryptStream(bdy);
    const td = await res;
   
    if(td?.url){
        if(isValidFunction(cb)){
            cb(td?.url);
        }
    }else{
        if(isValidFunction(cb)){
            cb(null);
        }
    }
  } 


