export const convert_mov_comprobantes  = async () => {
    let comp2save = [];
        
    
    let td =  getStore("feedfMbls_list");

    td.map(async (itm, ind2)=>{

        if(itm.comprobanteId){
            return
        }
             

        

        
        let ffm = {...itm}
        let itmFrn = {...itm};
        let deb_type = "debit";
		let cred_type = "credit";
			

        if(itmFrn?.movementType==="expense"){
            deb_type = "credit";
            cred_type = "debit";
        }

        
        let descr = itmFrn?.title + "; "+ itmFrn?.description;


        let categoryDtls =  getStore("categories_ids")?.[itmFrn?.categoryId];

        let rc1 = {};
        rc1.amount = itmFrn?.amount;
        rc1.movementId = itmFrn?.movementId;
        rc1.description =  descr;
        rc1.date = itmFrn?.date;


        let rc2 = {...rc1};

        rc1["account"] = getStore("global_account_params")?.cash_bank.account;
        rc1.type = deb_type;
        

        rc2["account"] = categoryDtls?.account;
        if(categoryDtls?.subAccount){
            rc2["subAccount"] = categoryDtls?.subAccount;
        }
        rc2.type = cred_type;

        let cmpListfromMbl = [rc2,rc1];


        if(!ffm["date"]){
			ffm["date"] = (new Date()).getTime()+4800;
		}
		else{
			ffm["date"] =(new Date(ffm["date"])).getTime()+4800;
		}
        
        let comprobanteId = await generateComprobanteIdFromNum(ffm["date"],ind2*1+4);
        
        ffm["comprobanteId"] =comprobanteId;
        
        
        ffm["document"] = ffm["document"]?.trim();
        
        
        
        cmpListfromMbl && ObjectKeys(cmpListfromMbl)?.map(async (element, indE)=>{
            let dataAcc = cmpListfromMbl[element];
            if(!isNaN(dataAcc["amount"] * 1) && dataAcc["amount"]*1 > 0){
                let nnfrm = {...ffm};
                nnfrm["account"] =  dataAcc["account"];
                if(dataAcc["subAccount"]){
                    nnfrm["subAccount"] =  dataAcc["subAccount"];
                }
                
                nnfrm["movementRef"] =  itm["movementId"];
                nnfrm["type"] =  dataAcc["type"];
                nnfrm["amount"] =  dataAcc["amount"] *1;
                nnfrm["operationId"] = gen16CodeId();

                nnfrm["document"] =  gen4NumCode()+"_"+genAlphDay(ffm["date"]);
        
                let bdyq5 = {...getStore(qryStore())?.add_opera};
                bdyq5.params = {
                    businessId:  getStore("profileUser")?.businessId,
                    year: (new Date(ffm["date"])).getFullYear()
                }
                bdyq5.form=nnfrm;
                comp2save.push(bdyq5)
            }
        });
        
        
        let bdyq2 = {...getStore(qryStore())?.upd__incms_expns};
        bdyq2.params = {
            businessId:  getStore("profileUser")?.businessId,
            "movementId": itm["movementId"],
            year:getStore("date_current_year"),
        }
        bdyq2.data2update={comprobanteId};
        comp2save.push(bdyq2)
    })

    setTimeout(() => {
        //console.log(comp2save)
        //fetchQueue(comp2save, fetchCSVInve)
    }, 4000);
    
}







