export function GroupbyAcc(arr, isPay) {
    let key =  "feedfMbl";
    var obj = {
        "operations":[]
    };
    let balance = 0;

    let arr1 = arr && ObjectKeys(arr)
    if (arr1.length > 0) {
      arr1.map((ele) => {
        let s = arr[ele];
        if(s["type"]){
            if(isPay){
                balance += s["type"] === "debit" ? s["amount"] * -1 : s["amount"] * 1;
            }
            else{
                balance += s["type"] === "credit" ? s["amount"] * -1 : s["amount"] * 1;
            }
            obj["operations"].push(convert4acc(s));
        }
      });
    } else {
      obj = null;
    }
    return obj;
  }



  export function convert4acc(s) {
    let nItm = {};
    nItm["feedfMbl"] =  getStore("feedfMbls_ids")?.[s["feedfMbl"]];
    nItm["sub_feedfMbl"] = getStore("sub_feedfMbls_ids")?.[s["subProvider"]];
    nItm["comprobanteId"] = s["comprobanteId"];
    nItm["document"] = s["document"];
    nItm["date"] = s["date"];
    if(s["type"]==="credit"){
        nItm["debit"] = 0;
        nItm["credit"] = s["amount"];
        
    }
    else if(s["type"]==="debit"){
        nItm["credit"] = 0;
        nItm["debit"] = s["amount"];
    }
    return nItm;
  }



  
//  sorting episodes comparing inputs to save in cache
export const sort_feedfMbl = (td, key) =>
callbackOnMemory(
	"sort_feedfMbl",
	[td],
	() => {
        let order = true;
		let sortedA = td && td.sort((a, b) => {
			let A = a[key] * 1;
			let B = b[key] *1;
			if (A < B) {
				return order ? -1 : 1;
			}
			if (A > B) {
				return order ? 1 : -1;
			}
			return 0;
        });
		return sortedA;
	}
);



export const sortComprobantesByDate = (td) =>
callbackOnMemory(
	"sortComprobantesByDate",
	[td],
	() => {
        let order = true;
        let key = "date";
		let sortedA = td && td.sort((a, b) => {
			let A =(new Date(a[key])).getTime();
			let B = (new Date(b[key])).getTime();
			if (A < B) {
				return order ? -1 : 1;
			}
			if (A > B) {
				return order ? 1 : -1;
			}
			return 0;
        });
		return sortedA;
	}
);

